const f = $('Start Form').first().json;
const roleRaw = String(f.role).trim();
const isIntern = String(f.job_type).toLowerCase().indexOf('intern') >= 0;
let pay = 'any';
pay = String(f.internship_pay || 'any').toLowerCase();
const role = isIntern && !/intern/i.test(roleRaw) ? roleRaw + ' internship' : roleRaw;
const city = String(f.city).trim();
const areaRaw = String(f.preferred_location || '').trim();
const level = String(f.experience).toLowerCase().indexOf('fresher') >= 0 ? 'freshers' : 'experienced';
const wholeCity = !areaRaw || /whole\s*city|entire\s*city|all\s*city|^all$|^any/i.test(areaRaw);
const areas = wholeCity ? [] : areaRaw.split(/[,;\/]+/).map(a => a.trim()).filter(Boolean);
const hire = ['hiring', 'vacancy', 'jobs', 'openings', 'careers', 'walk-in interview', 'recruitment'];
const contact = ['HR email', 'HR manager contact email', 'careers email', 'send resume to email', 'HR contact number and email'];
const sectors = ['IT company', 'software company', 'startup', 'manufacturing company', 'textile company', 'finance company', 'trading company', 'marketing agency', 'private limited company', 'CA firm', 'export house', 'real estate company'];
const set = new Set();
const add = q => set.add(q.replace(/\s+/g, ' ').trim());
const places = wholeCity ? [city] : areas.map(a => a + ' ' + city);
for (const place of places) {
  for (const h of hire) add(role + ' ' + h + ' ' + place);
  for (const c of contact) add(role + ' ' + c + ' ' + place);
  add(role + ' ' + level + ' ' + place + ' 2026');
  if (isIntern && pay === 'paid') add(role + ' stipend paid ' + place);
  add('companies in ' + place + ' HR email careers');
  add(place + ' company list with contact email');
}
add(role + ' jobs in ' + city + ' for ' + level);
add('top companies in ' + city + ' hiring ' + role + ' contact email');
if (wholeCity) {
  for (const sec of sectors) {
    add(sec + ' ' + city + ' hiring ' + role + ' HR email');
    add('top ' + sec + 's in ' + city + ' careers contact email');
    add(sec + ' ' + city + ' ' + role + ' vacancy ' + level);
  }
  add(role + ' ' + city + ' industrial area companies HR email');
  add(role + ' ' + city + ' walk-in interview HR contact');
}
const queries = Array.from(set).slice(0, 150);
return queries.map(q => ({ json: { query: q } }));

return $input.all().map(i => {
  const web = (i.json.data && i.json.data.web) || [];
  return { json: { searchText: JSON.stringify(web).slice(0, 30000) } };
}).filter(i => i.json.searchText.length > 10);

const f = $('Start Form').first().json;
const isIntern = String(f.job_type).toLowerCase().indexOf('intern') >= 0;
let pay = 'any';
pay = String(f.internship_pay || 'any').toLowerCase();
const seen = new Set();
const rows = [];
for (const i of $input.all()) {
  const j = i.json;
  const email = String(j.hr_email).trim().toLowerCase();
  if (seen.has(email)) continue;
  if (isIntern && pay === 'paid' && j.paid_internship === 'no') continue;
  if (isIntern && pay === 'unpaid' && j.paid_internship === 'yes') continue;
  seen.add(email);
  rows.push({ company_name: j.company_name, hr_email: email, email_type: j.email_type, five_day_week: j.five_day_week, paid_internship: j.paid_internship || 'unknown', stipend_info: j.stipend_info || '', source_url: j.source_url });
}
const rank = r => (isIntern && pay !== 'unpaid' && r.paid_internship === 'yes' ? 0 : 1) + (r.email_type === 'public' ? 0 : 0.5);
rows.sort((a, b) => rank(a) - rank(b));
return rows.slice(0, 100).map((r, idx) => ({ json: Object.assign({ no: idx + 1 }, r) }));

const items = $input.all();
const esc = v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"';
const csv = ['No,Company Name,HR Email,Email Type,Paid Internship,Stipend Info,Five Day Week,Source URL'].concat(items.map(r => [r.json.no, r.json.company_name, r.json.hr_email, r.json.email_type, r.json.paid_internship, r.json.stipend_info, r.json.five_day_week, r.json.source_url].map(esc).join(','))).join('\n');
const file = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'surat-ai-ml-companies.csv', 'text/csv');
const resume = $('Download Resume PDF').first().binary.resume;
return items.map(i => ({ json: i.json, binary: { csvfile: file, resume } }));

const rows = $('Prepare Rows with Resume').all();
const results = $input.all();
let sent = 0;
let failed = 0;
const lines = rows.map((r, idx) => {
  const res = results[idx] ? results[idx].json : {};
  const ok = !!res.id && !res.error;
  if (ok) sent++; else failed++;
  const status = ok ? 'DRAFTED' : 'FAILED';
  return '<tr><td>' + r.json.no + '</td><td>' + r.json.company_name + '</td><td>' + r.json.hr_email + '</td><td>' + r.json.paid_internship + (r.json.stipend_info ? ' (' + r.json.stipend_info + ')' : '') + '</td><td><b>' + status + '</b></td></tr>';
});
const html = '<p>Outreach drafts created in Gmail (nothing sent yet).</p><p>Total: ' + rows.length + ' | Drafted: ' + sent + ' | Failed: ' + failed + '</p>' +
  '<table border="1" cellpadding="6" cellspacing="0"><tr><th>No</th><th>Company</th><th>HR Email</th><th>Paid?</th><th>Status</th></tr>' + lines.join('') + '</table>' +
  '<p>Note: "guessed" addresses may bounce. Check your Gmail inbox for delivery failure notices.</p>';
return [{ json: { total: rows.length, sent, failed, html }, binary: { data: $('Create CSV File').first().binary.csvfile } }];
